// Logos des enseignes (base64 optimisé) + config par marque.
// Embarqués en base64 pour l'insertion directe dans les PDF (expo-print),
// aussi bien sur web que mobile, sans dépendre du réseau.
//
// L'identité est déduite en priorité des champs structurés du restaurant,
// avec le nom et l'ancienne couleur comme repli pour les lignes historiques.

export const LOGO_SAMER = 'data:image/png;base64,'

export const LOGO_KAYAN = 'data:image/png;base64,'

export const MARQUES = {
  samer: {
    id: 'samer',
    nom: 'CHEZ SAMER',
    societe: 'CHEZ SAMER SARL',
    sigle: 'CS',
    logo: LOGO_SAMER,
    adresse: '21 BP 915 Abidjan 21',
    contact: 'Tél. : 0152111119  ·  chezsamerrestaurant@gmail.com',
    accent: '#EF9F27',
  },
  alkayan: {
    id: 'alkayan',
    nom: 'AL KAYAN',
    societe: 'AL KAYAN',
    sigle: 'AK',
    logo: LOGO_KAYAN,
    adresse: '',   // à compléter si besoin
    contact: '',   // à compléter si besoin
    accent: '#7A1E1E',
  },
  alabraise: {
    id: 'alabraise',
    nom: 'À LA BRAISE',
    societe: 'À LA BRAISE CHEZ MAPAU',
    sigle: 'AB',
    logo: '',
    adresse: 'Yopougon Maroc, à 100 m de l’antenne Maroc',
    contact: 'Tél. : 07 01 11 11 18',
    accent: '#D99A2B',
  },
}

function texteIdentite(resto) {
  if (resto && typeof resto === 'object') {
    return [resto.code, resto.marque, resto.famille, resto.nom].filter(Boolean).join(' ')
  }
  return String(resto || '')
}

// Déduit la marque depuis une ligne restaurant ou, pour compatibilité, son nom.
export function marquePourResto(resto) {
  const identite = texteIdentite(resto)
  if (/ALA_BRAISE|\bbraise\b/i.test(identite)) return MARQUES.alabraise
  if (/al[ _-]*kayan|\bkayan\b/i.test(identite)) return MARQUES.alkayan
  return MARQUES.samer
}

export function couleurPourResto(resto) {
  const explicite = resto && typeof resto === 'object'
    ? (resto.couleur_principale || resto.couleur)
    : null
  if (/^#[0-9a-f]{6}$/i.test(explicite || '')) return explicite
  const marque = marquePourResto(resto)
  if (marque.id === 'alkayan') return '#2D7D46'
  return marque.accent
}
